// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/git/ChangesShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * The Changes view scene: the web session's tile with its code panel open
 * beside the terminal on Changes (what the footer's amber branch icon and the
 * palette's Show changes open, openTileChanges in src/state/store.ts), a
 * changed file's diff picked.
 *
 * The card frames the code panel at about its real size: the tile sits in
 * the bottom right cell of the 1440 x 900 window's grid, and the card runs
 * from the blank right edge of its terminal (past the end of its 57 columns)
 * to the wallpaper beyond the window, and from the gap above the tile to the
 * wallpaper below it. The tile's height makes the diff end between two lines.
 */
import type { CSSProperties } from "react";
import { Term } from "../../home/AppUI";
import { AnsiScreen } from "../../home/ansi";
import type { BackdropScene } from "../../home/Backdrop";
import { Shot } from "../../home/Chrome";
import { ActiveCanvas } from "../../home/Interactive";
import { AppWindow, WIN_SIZE } from "../../home/Scenes";
import { ChangesPanel, changesPanelHeight, CODE_SPLIT, type ReviewComment } from "./ChangesPanel";
import { GitTile } from "./GitTile";

/* The window's grid runs from x 10 to 1430 and y 52 to 890, with 10px gaps. */
const GRID_LEFT = 10;
const GRID_RIGHT = 1430;
const GRID_BOTTOM = 890;
const GRID_HEIGHT = 838;
const GAP = 10;
/** The framed tile's width: 475px of terminal (its 57 columns and padding) beside the panel. */
const TILE_WIDTH = 1252;
/** A tile's header, footer and borders around its body. */
const TILE_CHROME = 1 + 30 + 22 + 1;
/** Where the card starts: 12px of the terminal's blank right edge before the panel. */
const TERMINAL_SHOWN = 12;
/** Wallpaper beyond the window's right and bottom edges, and the gap shown above the tile. */
const MARGIN = 14;
const GAP_SHOWN = 5;

export function ChangesFrame({
  backdrop,
  rows,
  treeOpen,
  comments,
}: {
  backdrop: BackdropScene;
  /** How many diff rows the editor shows whole. */
  rows: number;
  treeOpen?: boolean;
  comments?: ReviewComment[];
}) {
  // Tenths of a pixel, as the rows' 17.5px and 20.7px heights add up.
  const tileHeight = Math.round((TILE_CHROME + changesPanelHeight(rows, comments?.length ?? 0)) * 10) / 10;
  const tileLeft = GRID_RIGHT - TILE_WIDTH;
  const tileTop = GRID_BOTTOM - tileHeight;
  const terminalWidth = (TILE_WIDTH - 2) * CODE_SPLIT;
  const cardLeft = tileLeft + 1 + terminalWidth - TERMINAL_SHOWN;
  const cardTop = tileTop - GAP_SHOWN;
  const card = { width: WIN_SIZE.width + MARGIN - cardLeft, height: Math.round(WIN_SIZE.height + MARGIN - cardTop) };
  const grid: CSSProperties = {
    gridTemplateColumns: `${tileLeft - GAP - GRID_LEFT}px ${TILE_WIDTH}px`,
    gridTemplateRows: `${Math.round((GRID_HEIGHT - GAP - tileHeight) * 10) / 10}px ${tileHeight}px`,
  };
  // The tile's cell, set by the app's grid, and the split handle's --code-split.
  const tileStyle: CSSProperties & Record<"--code-split", string> = {
    gridColumn: "2",
    gridRow: "2",
    "--code-split": `${CODE_SPLIT * 100}%`,
  };
  return (
    <Shot id={backdrop} width={card.width} height={card.height} className="git-code-scene">
      <AppWindow box={{ left: -cardLeft, top: -cardTop, ...WIN_SIZE }}>
        <ActiveCanvas
          style={grid}
          tiles={[
            <GitTile
              key="web"
              title="web"
              kbd="⌘1"
              codeOpen
              bodyClass="tile-body-code-side-by-side"
              style={tileStyle}
              footer={{ session: "web", git: { branch: "main", dirty: true, ahead: 0, behind: 0 }, web: true, agent: true, path: "~/fieldnotes/web", started: "00:58" }}
            >
              <Term>
                <AnsiScreen id="web-57" />
              </Term>
              <ChangesPanel treeOpen={treeOpen} comments={comments} />
            </GitTile>,
          ]}
        />
      </AppWindow>
    </Shot>
  );
}

/** The changed files beside NoteList.tsx's diff, down to its first modified line and the one after. */
export function ChangesShot() {
  return <ChangesFrame backdrop="palette" rows={24} />;
}
